"use client"

import * as React from "react"
import { Plus, FileText, Download, Search, Trash2, X, Command, Filter, FolderOpen } from "@/components/ui/proicons"
import { motion, AnimatePresence } from "framer-motion"
import { SbBtn, SbModal, SbModalHeader, SbModalBody, SbModalFooter, useToast } from "@/components/ui/sb"
import { generateCertificatePDF, downloadPDF, generateCertificateDOCX, downloadDOCX } from "@/lib/pdf"
import { MiniWordEditor } from "@/components/ui/mini-word-editor"
import { DocumentLibrary } from "@/components/shared/document-library"

interface Certificate { id: string; student_id: string | null; student_name: string; type: string; issue_date: string; file_url: string | null; status: string }
interface StudentOption { id: string; first_name: string; last_name: string; document_number: string; grade: string; section: string }

const CERT_TYPES = ["Constancia de matrícula", "Certificado de studies", "Constancia de conducta", "Certificado de notas", "Constancia de no deuda"]

const statusConfig: Record<string, { label: string; color: string; dot: string; bg: string }> = {
  emitido: { label: "Emitido", color: "text-emerald-600", dot: "bg-emerald-500", bg: "bg-emerald-500/8" },
  pendiente: { label: "Pendiente", color: "text-amber-600", dot: "bg-amber-500", bg: "bg-amber-500/8" },
  anulado: { label: "Anulado", color: "text-red-600", dot: "bg-red-500", bg: "bg-red-500/8" },
}

const listItem = {
  hidden: { opacity: 0, y: -10 },
  show: { opacity: 1, y: 0 },
  exit: { opacity: 0, filter: "blur(8px)", y: -10 },
}

function highlightMatch(text: string, query: string) {
  if (!query.trim()) return text
  const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi')
  return text.replace(regex, '<mark class="bg-sb-on-surface/15 text-sb-on-surface rounded px-0.5">$1</mark>')
}

export default function CertificadosPage() {
  const [certs, setCerts] = React.useState<Certificate[]>([])
  const [loading, setLoading] = React.useState(true)
  const [dialogOpen, setDialogOpen] = React.useState(false)
  const [searchInput, setSearchInput] = React.useState("")
  const [search, setSearch] = React.useState("")
  const [filterStatus, setFilterStatus] = React.useState("all")
  const [isFocused, setIsFocused] = React.useState(false)
  const [formData, setFormData] = React.useState({ student_id: "", student_name: "", type: "", file: null as File | null, custom_content: "" })
  const [students, setStudents] = React.useState<StudentOption[]>([])
  const [studentSearch, setStudentSearch] = React.useState("")
  const [showEditor, setShowEditor] = React.useState(false)
  const [saving, setSaving] = React.useState(false)
  const [deleteId, setDeleteId] = React.useState<string | null>(null)
  const [deleting, setDeleting] = React.useState(false)
  const [libraryOpen, setLibraryOpen] = React.useState(false)
  const { toast } = useToast()

  const debounceRef = React.useRef<NodeJS.Timeout | undefined>(undefined)
  const inputRef = React.useRef<HTMLInputElement>(null)

  React.useEffect(() => { fetchCerts(); fetchStudents() }, [])

  const fetchStudents = async () => {
    try {
      const res = await fetch("/api/secretario/enrollments")
      if (res.ok) {
        const data = await res.json()
        const unique = new Map<string, StudentOption>()
        data.forEach((e: any) => {
          if (e.student_id && !unique.has(e.student_id)) {
            unique.set(e.student_id, {
              id: e.student_id,
              first_name: e.first_name || "",
              last_name: e.last_name || "",
              document_number: e.document_number || "",
              grade: e.grade || "",
              section: e.section || "",
            })
          }
        })
        setStudents(Array.from(unique.values()))
      }
    } catch {}
  }

  // Keyboard shortcut: Ctrl/Cmd + K
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault()
        inputRef.current?.focus()
        inputRef.current?.select()
      }
    }
    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [])

  React.useEffect(() => () => clearTimeout(debounceRef.current), [])

  const onSearchChange = (val: string) => {
    setSearchInput(val)
    clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => setSearch(val), 300)
  }

  const clearSearch = () => { setSearchInput(""); setSearch("") }

  const fetchCerts = async () => {
    try { const res = await fetch("/api/secretario/certificados"); if (res.ok) setCerts(await res.json()) }
    catch {} finally { setLoading(false) }
  }

  const handleCreate = async () => {
    setSaving(true)
    try {
      const fd = new FormData()
      if (formData.student_id) fd.append('student_id', formData.student_id)
      fd.append('student_name', formData.student_name)
      fd.append('type', formData.type)
      if (formData.file) fd.append('file', formData.file)
      const res = await fetch("/api/secretario/certificados", { method: "POST", body: fd })
      if (res.ok) { setDialogOpen(false); setFormData({ student_id: "", student_name: "", type: "", file: null, custom_content: "" }); setStudentSearch(""); setShowEditor(false); fetchCerts(); toast("Certificado generado", "success") }
      else { const data = await res.json(); toast(data.error || "Error al generar", "error") }
    } catch (e) { console.error(e); toast("Error de conexión", "error") } finally { setSaving(false) }
  }

  const handleDownloadPDF = async (cert: Certificate) => {
    try {
      const res = await fetch("/api/secretario/stats")
      const stats = await res.json().catch(() => ({}))
      const instName = stats.institution_name || "Institución Educativa"
      const instCode = stats.institution_code || "IE-001"

      const doc = generateCertificatePDF({
        student_name: cert.student_name,
        type: cert.type,
        issue_date: cert.issue_date || new Date().toISOString(),
        institution: { name: instName, code: instCode },
      })
      const filename = `certificado_${cert.student_name.replace(/\s+/g, '_')}_${cert.type.replace(/\s+/g, '_')}.pdf`
      downloadPDF(doc, filename)
      toast("PDF descargado", "success")
    } catch (e) {
      console.error(e)
      toast("Error al generar PDF", "error")
    }
  }

  const handlePreviewPDF = async () => {
    try {
      const res = await fetch("/api/secretario/stats")
      const stats = await res.json().catch(() => ({}))
      const instName = stats.institution_name || "Institución Educativa"
      const instCode = stats.institution_code || "IE-001"

      const doc = generateCertificatePDF({
        student_name: formData.student_name,
        type: formData.type,
        issue_date: new Date().toISOString(),
        institution: { name: instName, code: instCode },
        custom_content: formData.custom_content || undefined,
      })
      const filename = `certificado_${formData.student_name.replace(/\s+/g, '_')}_${formData.type.replace(/\s+/g, '_')}.pdf`
      downloadPDF(doc, filename)
      toast("PDF descargado", "success")
    } catch (e) {
      console.error(e)
      toast("Error al generar PDF", "error")
    }
  }

  const handleDownloadDOCX = async (cert: Certificate) => {
    try {
      const res = await fetch("/api/secretario/stats")
      const stats = await res.json().catch(() => ({}))
      const instName = stats.institution_name || "Institución Educativa"
      const instCode = stats.institution_code || "IE-001"

      const blob = await generateCertificateDOCX({
        student_name: cert.student_name,
        type: cert.type,
        issue_date: cert.issue_date || new Date().toISOString(),
        institution: { name: instName, code: instCode },
      })
      const filename = `certificado_${cert.student_name.replace(/\s+/g, '_')}_${cert.type.replace(/\s+/g, '_')}.docx`
      await downloadDOCX(blob, filename)
      toast("DOCX descargado", "success")
    } catch (e) {
      console.error(e)
      toast("Error al generar DOCX", "error")
    }
  }

  const handlePreviewDOCX = async () => {
    try {
      const res = await fetch("/api/secretario/stats")
      const stats = await res.json().catch(() => ({}))
      const instName = stats.institution_name || "Institución Educativa"
      const instCode = stats.institution_code || "IE-001"

      const blob = await generateCertificateDOCX({
        student_name: formData.student_name,
        type: formData.type,
        issue_date: new Date().toISOString(),
        institution: { name: instName, code: instCode },
        custom_content: formData.custom_content || undefined,
      })
      const filename = `certificado_${formData.student_name.replace(/\s+/g, '_')}_${formData.type.replace(/\s+/g, '_')}.docx`
      await downloadDOCX(blob, filename)
      toast("DOCX descargado", "success")
    } catch (e) {
      console.error(e)
      toast("Error al generar DOCX", "error")
    }
  }

  const handleDelete = async () => {
    if (!deleteId) return
    setDeleting(true)
    try {
      const res = await fetch(`/api/secretario/certificados/${deleteId}`, { method: "DELETE" })
      if (res.ok) { setDeleteId(null); fetchCerts(); toast("Certificado eliminado", "success") }
      else { const data = await res.json(); toast(data.error || "Error al eliminar", "error") }
    } catch (e) { console.error(e); toast("Error de conexión", "error") } finally { setDeleting(false) }
  }

  const filtered = certs.filter(c => {
    const q = search.toLowerCase()
    const matchSearch = !q || c.student_name.toLowerCase().includes(q) || c.type.toLowerCase().includes(q)
    const matchStatus = filterStatus === "all" || c.status === filterStatus
    return matchSearch && matchStatus
  })

  const tabs = [
    { id: "all", label: "Todos", count: certs.length },
    { id: "emitido", label: "Emitidos", count: certs.filter(c => c.status === "emitido").length },
    { id: "pendiente", label: "Pendientes", count: certs.filter(c => c.status === "pendiente").length },
    { id: "anulado", label: "Anulados", count: certs.filter(c => c.status === "anulado").length },
  ]

  const hasActiveSearch = search || filterStatus !== "all"

  return (
    <div className="space-y-5">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mb-8"
        >
          <div>
            <h1 className="text-2xl font-bold text-sb-on-surface tracking-tight">Certificados</h1>
            <p className="text-sm text-sb-on-surface-variant/50 mt-1">Genera certificados para alumnos</p>
          </div>
          <div className="flex items-center gap-2">
            <SbBtn variant="outlined" rounded className="flex items-center gap-2" onClick={() => setLibraryOpen(true)}>
              <FolderOpen className="h-3.5 w-3.5" />
              Biblioteca
            </SbBtn>
            <SbBtn variant="filled" rounded className="flex items-center gap-2" onClick={() => setDialogOpen(true)}>
              <Plus className="h-3.5 w-3.5" />
              Nuevo certificado
            </SbBtn>
          </div>
        </motion.div>

        {/* Search Bar - Premium */}
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.05 }}
          className="mb-4"
        >
          <div className={`bg-sb-surface rounded-2xl transition-all duration-300 ${isFocused ? 'ring-2 ring-sb-on-surface/10 shadow-lg shadow-sb-on-surface/5' : ''}`}>
            <div className="flex items-center gap-2 p-2">
              <div className="relative flex-1">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-sb-on-surface-variant/30" />
                <input
                  ref={inputRef}
                  placeholder="Buscar por nombre del alumno o tipo de certificado..."
                  value={searchInput}
                  onChange={e => onSearchChange(e.target.value)}
                  onFocus={() => setIsFocused(true)}
                  onBlur={() => setIsFocused(false)}
                  className="w-full h-12 pl-12 pr-20 bg-transparent text-sm text-sb-on-surface placeholder:text-sb-on-surface-variant/30 focus:outline-none"
                />
                <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1.5">
                  {searchInput && (
                    <button
                      onClick={clearSearch}
                      className="h-7 w-7 flex items-center justify-center rounded-lg text-sb-on-surface-variant/30 hover:text-sb-on-surface-variant hover:bg-sb-surface-container transition-colors"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  )}
                  <div className="hidden sm:flex items-center gap-1 px-2 py-1 rounded-lg bg-sb-surface-container/50 text-sb-on-surface-variant/30">
                    <Command className="h-3 w-3" />
                    <span className="text-[10px] font-medium">K</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </motion.div>

        {/* Tabs + Results Count */}
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.08 }}
          className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 mb-6"
        >
          <div className="flex gap-1 p-1 bg-sb-surface rounded-xl">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setFilterStatus(tab.id)}
                className={`px-4 py-2 rounded-lg text-xs font-medium transition-all ${
                  filterStatus === tab.id
                    ? "bg-sb-on-surface text-sb-surface"
                    : "text-sb-on-surface-variant/60 hover:bg-sb-surface-container"
                }`}
              >
                {tab.label}
                <span className={`ml-1.5 text-[10px] ${filterStatus === tab.id ? "text-sb-surface/60" : "text-sb-on-surface-variant/30"}`}>
                  {tab.count}
                </span>
              </button>
            ))}
          </div>

          <div className="flex items-center gap-3">
            {hasActiveSearch && !loading && (
              <p className="text-xs text-sb-on-surface-variant/40">
                {filtered.length} resultado{filtered.length !== 1 ? "s" : ""}
                {search && <> para "<span className="text-sb-on-surface font-medium">{search}</span>"</>}
              </p>
            )}
            {hasActiveSearch && (
              <button onClick={() => { clearSearch(); setFilterStatus("all") }} className="text-[10px] text-sb-on-surface-variant/30 hover:text-sb-on-surface-variant/60 transition-colors">
                Limpiar
              </button>
            )}
          </div>
        </motion.div>

        {/* List */}
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
        >
          {loading ? (
            <div className="bg-sb-surface rounded-2xl">
              {[1, 2, 3].map(i => (
                <div key={i} className="h-16 animate-pulse border-b border-sb-outline-variant/10 last:border-0" />
              ))}
            </div>
          ) : filtered.length === 0 ? (
            <div className="bg-sb-surface rounded-2xl py-20 text-center">
              <div className="h-16 w-16 rounded-2xl bg-sb-surface-container flex items-center justify-center mx-auto mb-4">
                <FileText className="h-7 w-7 text-sb-on-surface-variant/20" />
              </div>
              <p className="text-sm font-medium text-sb-on-surface-variant/40">
                {hasActiveSearch ? "Sin resultados para esta búsqueda" : "Sin certificados registrados"}
              </p>
              {hasActiveSearch && (
                <button onClick={() => { clearSearch(); setFilterStatus("all") }} className="mt-3 text-xs text-sb-on-surface hover:underline">
                  Limpiar filtros
                </button>
              )}
            </div>
          ) : (
            <div className="bg-sb-surface rounded-2xl overflow-hidden">
              {/* Table Header */}
              <div className="grid grid-cols-[1fr_1.5fr_100px_100px_80px] gap-4 px-5 py-3 border-b border-sb-outline-variant/10">
                <span className="text-[10px] font-semibold text-sb-on-surface-variant/40 uppercase tracking-wider">Alumno</span>
                <span className="text-[10px] font-semibold text-sb-on-surface-variant/40 uppercase tracking-wider">Tipo</span>
                <span className="text-[10px] font-semibold text-sb-on-surface-variant/40 uppercase tracking-wider">Fecha</span>
                <span className="text-[10px] font-semibold text-sb-on-surface-variant/40 uppercase tracking-wider">Estado</span>
                <span className="text-[10px] font-semibold text-sb-on-surface-variant/40 uppercase tracking-wider text-right">Acciones</span>
              </div>

              {/* Table Body */}
              <div className="divide-y divide-sb-outline-variant/8">
                <AnimatePresence>
                  {filtered.map((c, i) => {
                    const st = statusConfig[c.status] || statusConfig.pendiente
                    return (
                      <motion.div
                        key={c.id}
                        variants={listItem}
                        initial="hidden"
                        animate="show"
                        exit="exit"
                        transition={{ delay: i * 0.02, duration: 0.3 }}
                        className="grid grid-cols-[1fr_1.5fr_100px_100px_80px] gap-4 px-5 py-4 items-center hover:bg-sb-surface-container-low/50 transition-colors"
                      >
                        {/* Student */}
                        <div className="flex items-center gap-3 min-w-0">
                          <div className="h-9 w-9 rounded-xl bg-sb-surface-container flex items-center justify-center shrink-0">
                            <span className="text-[11px] font-semibold text-sb-on-surface-variant/50">
                              {c.student_name.split(" ").map(n => n[0]).join("").slice(0, 2).toUpperCase()}
                            </span>
                          </div>
                          <span
                            className="text-sm font-medium text-sb-on-surface truncate"
                            dangerouslySetInnerHTML={{ __html: highlightMatch(c.student_name, search) }}
                          />
                        </div>

                        {/* Type */}
                        <span
                          className="text-sm text-sb-on-surface/70 truncate"
                          dangerouslySetInnerHTML={{ __html: highlightMatch(c.type, search) }}
                        />

                        {/* Date */}
                        <span className="text-xs text-sb-on-surface-variant/50">
                          {c.issue_date ? new Date(c.issue_date).toLocaleDateString("es-PE", { day: "2-digit", month: "short" }) : "—"}
                        </span>

                        {/* Status */}
                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[11px] font-medium ${st.color} ${st.bg}`}>
                          <span className={`h-1.5 w-1.5 rounded-full ${st.dot}`} />
                          {st.label}
                        </span>

                        {/* Actions */}
                        <div className="flex items-center justify-end gap-1">
                          {c.file_url ? (
                            <a
                              href={c.file_url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="h-8 w-8 flex items-center justify-center rounded-lg text-sb-on-surface-variant/40 hover:text-sb-on-surface hover:bg-sb-surface-container transition-colors"
                            >
                              <Download className="h-4 w-4" />
                            </a>
                          ) : (
                            <div className="relative group">
                              <button
                                className="h-8 w-8 flex items-center justify-center rounded-lg text-sb-on-surface-variant/40 hover:text-sb-on-surface hover:bg-sb-surface-container transition-colors"
                                title="Descargar"
                              >
                                <Download className="h-4 w-4" />
                              </button>
                              <div className="absolute right-0 top-full mt-1 bg-sb-surface rounded-xl shadow-lg border border-sb-outline-variant/10 py-1 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-10 w-32">
                                <button
                                  onClick={() => handleDownloadPDF(c)}
                                  className="w-full px-3 py-2 text-left text-xs text-sb-on-surface hover:bg-sb-surface-container-low/50 flex items-center gap-2"
                                >
                                  <FileText className="h-3.5 w-3.5 text-red-500" />
                                  PDF
                                </button>
                                <button
                                  onClick={() => handleDownloadDOCX(c)}
                                  className="w-full px-3 py-2 text-left text-xs text-sb-on-surface hover:bg-sb-surface-container-low/50 flex items-center gap-2"
                                >
                                  <FileText className="h-3.5 w-3.5 text-blue-500" />
                                  DOCX
                                </button>
                              </div>
                            </div>
                          )}
                          <button
                            onClick={() => setDeleteId(c.id)}
                            className="h-8 w-8 flex items-center justify-center rounded-lg text-sb-on-surface-variant/30 hover:text-red-500 hover:bg-red-500/10 transition-colors"
                          >
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </div>
                      </motion.div>
                    )
                  })}
                </AnimatePresence>
              </div>
            </div>
          )}
        </motion.div>

      {/* Delete Modal */}
      <SbModal open={!!deleteId} onClose={() => setDeleteId(null)} maxWidth="400px">
        <SbModalHeader title="Eliminar Certificado" onClose={() => setDeleteId(null)} />
        <SbModalBody>
          <p className="text-sm text-sb-on-surface-variant/60">
            ¿Eliminar este certificado? Esta acción es irreversible.
          </p>
        </SbModalBody>
        <SbModalFooter>
          <SbBtn rounded onClick={() => setDeleteId(null)}>Cancelar</SbBtn>
          <SbBtn variant="danger" rounded onClick={handleDelete} disabled={deleting}>
            {deleting ? "Eliminando..." : "Eliminar"}
          </SbBtn>
        </SbModalFooter>
      </SbModal>

      {/* Create Modal */}
      <SbModal open={dialogOpen} onClose={() => setDialogOpen(false)} maxWidth="420px">
        <SbModalHeader title="Generar Certificado" onClose={() => setDialogOpen(false)} />
        <SbModalBody>
          <motion.div
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-4"
          >
            <div>
              <label className="text-[10px] font-semibold text-sb-on-surface-variant/40 uppercase tracking-wider mb-2 block">Buscar alumno (opcional)</label>
              <input
                placeholder="Escribir nombre o DNI..."
                value={studentSearch}
                onChange={e => setStudentSearch(e.target.value)}
                className="sb-input rounded-xl text-sm h-10 w-full"
              />
              {studentSearch && students.length > 0 && (
                <div className="mt-1 max-h-40 overflow-y-auto border border-sb-outline-variant/10 rounded-xl bg-sb-surface">
                  {students
                    .filter(s => {
                      const q = studentSearch.toLowerCase()
                      const name = `${s.first_name} ${s.last_name}`.toLowerCase()
                      return name.includes(q) || s.document_number.includes(q)
                    })
                    .slice(0, 10)
                    .map(s => (
                      <button
                        key={s.id}
                        type="button"
                        onClick={() => {
                          setFormData({ ...formData, student_id: s.id, student_name: `${s.first_name} ${s.last_name}` })
                          setStudentSearch(`${s.first_name} ${s.last_name}`)
                        }}
                        className="w-full text-left px-3 py-2 hover:bg-sb-surface-container-low/50 text-sm transition-colors"
                      >
                        <span className="font-medium">{s.first_name} {s.last_name}</span>
                        <span className="text-xs text-sb-on-surface-variant/40 ml-2">DNI: {s.document_number} | {s.grade}° {s.section}</span>
                      </button>
                    ))}
                </div>
              )}
            </div>
            <div>
              <label className="text-[10px] font-semibold text-sb-on-surface-variant/40 uppercase tracking-wider mb-2 block">Nombre del alumno *</label>
              <input
                placeholder="Juan Pérez López"
                value={formData.student_name}
                onChange={e => setFormData({ ...formData, student_name: e.target.value, student_id: "" })}
                className="sb-input rounded-xl text-sm h-10 w-full"
              />
            </div>
            <div>
              <label className="text-[10px] font-semibold text-sb-on-surface-variant/40 uppercase tracking-wider mb-2 block">Tipo de certificado *</label>
              <select
                value={formData.type}
                onChange={e => setFormData({ ...formData, type: e.target.value })}
                className="sbf-native-select w-full"
              >
                <option value="">Seleccionar tipo...</option>
                {CERT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-semibold text-sb-on-surface-variant/40 uppercase tracking-wider mb-2 block">Archivo PDF (opcional)</label>
              <input
                type="file"
                accept=".pdf,image/*"
                onChange={e => setFormData({ ...formData, file: e.target.files?.[0] || null })}
                className="sb-input rounded-xl text-sm h-10 w-full file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-medium file:bg-sb-surface-container file:text-sb-on-surface"
              />
            </div>

            {/* Custom Content Editor */}
            {formData.student_name && formData.type && (
              <div className="pt-2">
                <button
                  type="button"
                  onClick={() => setShowEditor(!showEditor)}
                  className="flex items-center gap-2 text-xs text-sb-on-surface-variant/50 hover:text-sb-on-surface transition-colors"
                >
                  <span className={`transition-transform duration-200 ${showEditor ? 'rotate-90' : ''}`}>▶</span>
                  {showEditor ? "Ocultar editor" : "Personalizar contenido del certificado"}
                </button>
                {showEditor && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: "auto" }}
                    exit={{ opacity: 0, height: 0 }}
                    className="mt-3"
                  >
                    <MiniWordEditor
                      content={formData.custom_content}
                      onChange={val => setFormData({ ...formData, custom_content: val })}
                      placeholder="Escribe el contenido personalizado del certificado..."
                      minHeight={150}
                    />
                    <p className="text-[10px] text-sb-on-surface-variant/30 mt-1.5">
                      Usa el editor para personalizar el texto. Si lo dejas vacío, se usará el texto predeterminado.
                    </p>
                  </motion.div>
                )}
              </div>
            )}
          </motion.div>
        </SbModalBody>
        <SbModalFooter>
          <SbBtn rounded onClick={() => setDialogOpen(false)}>Cancelar</SbBtn>
          {formData.student_name && formData.type && (
            <>
              <SbBtn variant="outlined" rounded onClick={handlePreviewPDF}>
                <Download className="h-3.5 w-3.5 mr-1.5" />
                PDF
              </SbBtn>
              <SbBtn variant="outlined" rounded onClick={handlePreviewDOCX}>
                <Download className="h-3.5 w-3.5 mr-1.5" />
                DOCX
              </SbBtn>
            </>
          )}
          <SbBtn variant="filled" rounded onClick={handleCreate} disabled={saving || !formData.student_name || !formData.type}>
            {saving ? "Generando..." : "Generar"}
          </SbBtn>
        </SbModalFooter>
      </SbModal>

      {/* Document Library */}
      <DocumentLibrary
        open={libraryOpen}
        onClose={() => setLibraryOpen(false)}
        mode="manage"
      />
    </div>
  )
}
